"""miner_2 2027-08-16: revalidate effective library factors + screen new candidates.
Data filtered to visible_through (2027-08-13) to avoid lookahead.
Rank IC h=10 on 15-asset cross-section; gate |IC|>=0.0070, |ICIR|>=0.0840.
"""
import pandas as pd
import numpy as np
from scipy.stats import spearmanr
import json, os, math

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX",
          "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
MACRO = {"DXY": "DXY.csv", "USDCNY": "USDCNY.csv", "USDJPY": "USDJPY.csv",
         "EURUSD": "EURUSD.csv", "VIX": "VIX.csv"}
VISIBLE_THROUGH = "2027-08-13"

def load_asset(a):
    df = pd.read_csv(f"../persistent/stock_data/{a}.csv")
    df["date"] = pd.to_datetime(df["date"])
    df = df[df["date"] <= pd.Timestamp(VISIBLE_THROUGH)].reset_index(drop=True)
    return df

def load_macro(m):
    df = pd.read_csv(f"../persistent/index_data/{MACRO[m]}")
    df["date"] = pd.to_datetime(df["date"])
    df = df[df["date"] <= pd.Timestamp(VISIBLE_THROUGH)].reset_index(drop=True)
    return df

PX = {a: load_asset(a) for a in ASSETS}
CLOSE = {a: dict(zip(px["date"], px["close"])) for a, px in PX.items()}
VOL = {a: dict(zip(px["date"], px["volume"])) for a, px in PX.items()}
MAC = {m: load_macro(m) for m in MACRO}
MAC_CLOSE = {m: dict(zip(df["date"], df["close"])) for m, df in MAC.items()}

ALL_DATES = sorted(set().union(*[set(c) for c in CLOSE.values()]))
RETS = {}
for a in ASSETS:
    ds = sorted(CLOSE[a])
    r = {}
    for i in range(1, len(ds)):
        r[ds[i]] = CLOSE[a][ds[i]] / CLOSE[a][ds[i-1]] - 1.0
    RETS[a] = r

def series_vals(a, f):
    """f(dict date->value) -> aligned date->value on asset's own dates"""
    ds = sorted(CLOSE[a])
    return {d: f(d, ds) for d in ds}

# ---------- factor implementations (dict date -> value per asset) ----------
def f_vol_price_corr(a, win=20):
    ds = sorted(CLOSE[a]); out = {}
    for i in range(win, len(ds)):
        seg = ds[i-win:i+1]
